    max_mob = K
    mob = compute_mobius(max_mob)
    total = 0
    for d in range(1, K + 1):
        m = K // d
        sum_k = 0
        for k in range(1, m + 1):
            term = mob[k] * ((m // k) ** 3)
            sum_k += term
        total += d * sum_k
    print(total)

